def transform(grid):
    # Find the background, then extend the last occupied row of each vertical
    # group to the right edge using color 1.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    active = [any(value != bg for value in row) for row in grid]
    for r, has_cells in enumerate(active):
        if has_cells and (r + 1 == len(grid) or not active[r + 1]):
            occupied = [c for c, value in enumerate(out[r]) if value != bg]
            for c in range(occupied[-1] + 1, len(out[r])):
                out[r][c] = 1
    return out
